import mermaid from 'mermaid';
import teleportIcons from "../../data/teleport-icons.json";
import iconPackPrefixes from "../../data/mermaid-icon-packs.json";

mermaid.registerIconPacks([
  // Custom icons loaded from src/mermaid-icons
  {
    name: teleportIcons.prefix,
    icons: teleportIcons,
  },
  // Subsets generated by scripts/prepare-files.mts containing only the icons
  // referenced in Mermaid diagrams: loaded on-demand. There is one subset for
  // each @iconify-json/<prefix> package in package.json, for example
  // https://icones.js.org/collection/logos
  ...iconPackPrefixes.map((prefix) => ({
    name: prefix,
    loader: () =>
      import(`../../data/${prefix}-icons.json`).then((module) => module.default),
  })),
]);
